--
-- Table structure for table `generated_clips`
--

DROP TABLE IF EXISTS `generated_clips`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `generated_clips` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_video_id` int NOT NULL,
  `destination_channel_id` int DEFAULT NULL,
  `clip_path` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `thumbnail_path` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `tags` text COLLATE utf8mb4_unicode_ci,
  `score` tinyint DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `start_time` float DEFAULT NULL,
  `end_time` float DEFAULT NULL,
  `youtube_video_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `scheduled_for` timestamp NULL DEFAULT NULL,
  `upload_error` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending_cut','pending','cutting','publishing','published','failed','approved','rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'pending_cut',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_generated_clips_video` (`source_video_id`),
  KEY `fk_generated_clips_destination_channel` (`destination_channel_id`),
  CONSTRAINT `fk_generated_clips_destination_channel` FOREIGN KEY (`destination_channel_id`) REFERENCES `destination_channels` (`id`),
  CONSTRAINT `fk_generated_clips_video` FOREIGN KEY (`source_video_id`) REFERENCES `source_videos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=738 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

